    // Check size 5.5
    const sizeSelect = document.getElementById('native_dropdown_selected_size_name');
    let has55 = false;
    let sizeText = "";
    if (sizeSelect) {
      const opt = Array.from(sizeSelect.options).find(o => o.text.includes('5.5'));
      if (opt) {
        has55 = !opt.disabled;
        sizeText = opt.text;
      }
    } else {
      const sizeBtns = Array.from(document.querySelectorAll('[id^="size_name_"], button, [data-defaultasin]')).filter(b => b.textContent.trim() === '5.5');
      if (sizeBtns.length > 0) {
        has55 = !sizeBtns[0].classList.contains('swatchUnavailable');
        sizeText = "5.5";
      }
    }

    return { title, price, has55, sizeText, bullets: bullets.slice(0, 4), desc: desc?.slice(0, 300) };
  });
  res.push({ url, ...data });
}

